CREATE OR REPLACE FUNCTION billing_private.capture_assignment_usage_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'billing_private'
AS $function$
begin
  if old.location_id is not null then
    perform billing_private.capture_location_usage(old.location_id, 'location_assignment');
  end if;
  if new.location_id is not null and new.location_id is distinct from old.location_id then
    perform billing_private.capture_location_usage(new.location_id, 'location_assignment');
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION billing_private.capture_published_assignment_organization_usage_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'billing_private'
AS $function$
declare
  target_shift_id uuid := coalesce(new.rota_published_shift_id, old.rota_published_shift_id);
  target_employee_id uuid := coalesce(new.employee_id, old.employee_id);
  target_source_record_id uuid := coalesce(new.id, old.id);
  target_organization_id text;
  target_location_id uuid;
  target_usage_at timestamptz;
begin
  select
    rota.organization_id,
    rota.location_id,
    (shift.day_date::timestamp at time zone 'Europe/London')
  into target_organization_id, target_location_id, target_usage_at
  from public.rota_published_shifts shift
  join public.rotas rota on rota.id = shift.rota_id
  where shift.id = target_shift_id;

  perform billing_private.capture_organization_employee_usage(
    target_organization_id,
    target_location_id,
    target_employee_id,
    'published_rota_assignment',
    target_source_record_id,
    target_usage_at
  );

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION billing_private.capture_published_assignment_usage_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'billing_private'
AS $function$
declare
  target_shift_id uuid := coalesce(new.rota_published_shift_id, old.rota_published_shift_id);
  target_location_id uuid;
begin
  select rota.location_id into target_location_id
  from public.rota_published_shifts shift
  join public.rotas rota on rota.id = shift.rota_id
  where shift.id = target_shift_id;

  if target_location_id is not null then
    perform billing_private.capture_location_usage(target_location_id, 'published_rota');
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_time_entry_as_recorded(p_entry_id uuid, p_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entry record;
  v_has_permission boolean;
  v_next_status text;
begin
  select *
    into v_entry
    from public.time_entries
   where id = p_entry_id
   for update;

  if v_entry.id is null then
    raise exception 'time_entry_not_found';
  end if;

  select exists (
    select 1
      from public.location_memberships membership
     where membership.location_id = v_entry.location_id
       and membership.user_id = p_user_id
       and membership.role = any(array['owner', 'admin', 'manager', 'supervisor'])
    union
    select 1
      from public.member member
     where member."organizationId" = v_entry.organization_id
       and member."userId" = p_user_id
       and member.role = any(array['owner', 'admin', 'manager', 'supervisor'])
  ) into v_has_permission;

  if not v_has_permission then
    raise exception 'time_entry_approval_forbidden';
  end if;

  if v_entry.status <> 'requires_review' then
    raise exception 'time_entry_not_in_review';
  end if;

  v_next_status := case when v_entry.clocked_out_at is null then 'open' else 'closed' end;

  update public.time_entries
     set status = v_next_status,
         notes = case
           when notes is null or notes = '' then 'Manager approved as recorded.'
           else notes || E'\nManager approved as recorded.'
         end,
         updated_by = p_user_id,
         updated_at = timezone('utc', now())
   where id = v_entry.id
   returning * into v_entry;

  insert into public.clock_events (
    time_entry_id,
    organization_id,
    location_id,
    employee_id,
    performed_by_user_id,
    event_type,
    reason
  )
  values (
    v_entry.id,
    v_entry.organization_id,
    v_entry.location_id,
    v_entry.employee_id,
    p_user_id,
    'manager_adjustment',
    'Manager approved as recorded.'
  );

  return jsonb_build_object(
    'id', v_entry.id,
    'status', v_entry.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_location_billing_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  created_billing_account_id uuid;
begin
  if new.billing_account_id is not null then
    return new;
  end if;

  if new.organization_id is null then
    raise exception 'Locations must belong to an organization.';
  end if;

  select id into created_billing_account_id
  from public.billing_accounts
  where scope = 'organization'
    and organization_id = new.organization_id
  limit 1;

  if created_billing_account_id is null then
    insert into public.billing_accounts (
      scope,
      organization_id
    ) values (
      'organization',
      new.organization_id
    )
    returning id into created_billing_account_id;
  end if;

  new.billing_account_id := created_billing_account_id;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_user_onboarding_preferences_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
